mapper.select:
SELECT COUNT(DISTINCT m.member_id) FROM mem_member m WHERE m.del_flag = '0'
AND m.dept_id IN #{id}
AND ( EXISTS (SELECT 1 FROM mem_points_record pr WHERE pr.member_id = m.member_id AND pr.del_flag = '0') OR EXISTS (SELECT 1 FROM mem_points_exchange pe WHERE pe.member_id = m.member_id AND pe.del_flag = '0') OR EXISTS (SELECT 1 FROM mem_seckill_record sr WHERE sr.member_id = m.member_id AND sr.del_flag = '0') )

SELECT DATE_FORMAT(create_time, '%Y-%m-%d') AS dateStr, COUNT(1) AS newCount FROM mem_member WHERE del_flag = '0'
AND dept_id IN #{id}
AND create_time >= #{startTime}
AND create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d') ORDER BY dateStr

SELECT CASE status WHEN '0' THEN '正常' WHEN '1' THEN '无效' WHEN '2' THEN '已退卡' ELSE '其他' END AS statusName, COUNT(1) AS memberCount FROM mem_member WHERE del_flag = '0'
AND dept_id IN #{id}
GROUP BY status ORDER BY memberCount DESC

SELECT s.seckill_name AS seckillName, COUNT(DISTINCT r.member_id) AS participantCount, COALESCE(SUM(r.total_amount), 0) AS revenue FROM mem_seckill s LEFT JOIN mem_seckill_record r ON r.seckill_id = s.seckill_id AND r.del_flag = '0' WHERE s.del_flag = '0'
AND s.dept_id IN #{id}
GROUP BY s.seckill_id, s.seckill_name ORDER BY revenue DESC

SELECT r.dept_id AS deptId, d.dept_name AS deptName, COUNT(DISTINCT r.member_id) AS participantCount, COALESCE(SUM(r.total_amount), 0) AS revenue FROM mem_seckill_record r LEFT JOIN sys_dept d ON d.dept_id = r.dept_id WHERE r.del_flag = '0'
AND r.dept_id IN #{id}
GROUP BY r.dept_id, d.dept_name ORDER BY revenue DESC

SELECT COALESCE(SUM(r.sale_amount), 0) FROM fin_sale_record r WHERE r.del_flag = '0'
AND r.dept_id IN #{id}
AND r.sale_date >= #{startTime}
AND r.sale_date < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
AND r.remark LIKE '%member%'

SELECT COALESCE(SUM(r.sale_amount), 0) FROM fin_sale_record r WHERE r.del_flag = '0'
AND r.dept_id IN #{id}
AND r.sale_date >= #{startTime}
AND r.sale_date < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
AND (r.remark IS NULL OR r.remark NOT LIKE '%member%')

SELECT DATE_FORMAT(m.create_time, '%Y-%m-%d') AS dateStr, COUNT(DISTINCT m.member_id) AS newMemberCount, 0 AS activeMemberCount, COALESCE(SUM(CASE WHEN r.sale_amount IS NOT NULL THEN r.sale_amount ELSE 0 END), 0) AS memberSales, 0 AS nonMemberSales FROM mem_member m LEFT JOIN fin_sale_record r ON r.dept_id = m.dept_id AND r.del_flag = '0' AND r.remark LIKE '%member%' AND DATE(r.sale_date) = DATE(m.create_time) WHERE m.del_flag = '0'
AND m.dept_id IN #{id}
AND m.create_time >= #{startTime}
AND m.create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
GROUP BY DATE_FORMAT(m.create_time, '%Y-%m-%d') ORDER BY dateStr

SELECT s.seckill_id AS activityId, s.seckill_name AS activityName, COALESCE(SUM(r.total_amount), 0) AS sales, 0 AS cost, COALESCE(SUM(r.total_amount), 0) AS profit, COUNT(DISTINCT r.member_id) AS participantCount FROM mem_seckill s LEFT JOIN mem_seckill_record r ON r.seckill_id = s.seckill_id AND r.del_flag = '0' WHERE s.del_flag = '0'
AND s.dept_id IN #{id}
GROUP BY s.seckill_id, s.seckill_name ORDER BY sales DESC

SELECT COUNT(*) FROM ( SELECT r.member_id FROM mem_seckill_record r WHERE r.del_flag = '0'
AND r.dept_id IN #{id}
GROUP BY r.member_id HAVING COUNT(r.record_id) > 1 ) repurchase_members

SELECT COUNT(1) FROM fin_sale_record r WHERE r.del_flag = '0' AND r.remark LIKE '%member%'
AND r.dept_id IN #{id}
AND r.sale_date >= #{startTime}
AND r.sale_date < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

SELECT COUNT(*) FROM ( SELECT r.sale_no FROM fin_sale_record r WHERE r.del_flag = '0' AND r.remark LIKE '%member%'
AND r.dept_id IN #{id}
AND r.sale_date >= #{startTime}
AND r.sale_date < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
GROUP BY r.sale_no HAVING COUNT(r.sale_id) > 1 ) repeat_buyers
